import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { ClaimCells } from '../../slots/defs/claimRow';
import { PersonCells, PersonHeads } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { counts, useClaims } from '../claims/useClaims';
import { useHeld, usePeople } from '../people/people.slot';
import { useSheetToday } from '../today/today.slot';
import { useUser } from '../session/useSession';
import { claimDueCents, rateOn, ratesKey, showHundredths, toHundredths, useRates, type Rate } from './useRates';
import { useSubmitOnce } from '../../mutation/useSubmitOnce';

const GRADES = ['A', 'B', 'C'] as const;
const RATE = /^\d{1,3}(\.\d{1,2})?$/;
const NA = 'n/a';

/** The rate (in hundredths of a percent) in force on the sheet's today for each grade that has one. */
function useRateByGrade(sheetId: string): Map<string, bigint> {
  const rates = useRates(sheetId);
  const today = useSheetToday(sheetId).data?.today;
  const byGrade = new Map<string, bigint>();
  if (today === undefined) return byGrade;
  for (const g of GRADES) {
    const r = rateOn(rates.data ?? [], g, today);
    if (r) byGrade.set(g, toHundredths(r.rate));
  }
  return byGrade;
}

/** A person's due-total in cents: their counted claims' already-rounded figures added up (0 with none). Null when
 *  their grade has no rate on the sheet's today, unless a counted settled or stated claim keeps a figure: then the figures
 *  there are, added up. */
function useDueTotals(sheetId: string): Map<number, bigint | null> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const today = useRateByGrade(sheetId);
  const held = useHeld(sheetId);
  const totals = new Map<number, bigint | null>();
  for (const p of people.data ?? []) {
    const counted = (claims.data ?? []).filter((c) => c.personId === p.id && counts(c, held));
    if (!today.has(p.grade) && !counted.some((c) => c.settledDue != null || (c.stated && c.statedDue != null))) {
      totals.set(p.id, null);
      continue;
    }
    let sum = 0n;
    for (const c of counted) sum += claimDueCents(rates.data ?? [], p.grade, c) ?? 0n;
    totals.set(p.id, sum);
  }
  return totals;
}

// The rate form: sets a grade's rate from a date (blank: from the beginning of time), replacing one
// already set for that grade and date. Every rate is listed under it, with each grade's rate in
// force on the sheet's today.
function RatesPanel({ sheetId }: { sheetId: string; user: string }) {
  const rates = useRates(sheetId);
  const [grade, setGrade] = useState<string>('A');
  const [pct, setPct] = useState('');
  const [from, setFrom] = useState('');
  const today = useSheetToday(sheetId).data?.today;
  const [user] = useUser();
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: async (body: { grade: string; rate: string; from: string }) => {
      if (body.rate.trim() === '') throw new Error('Enter a rate');
      if (!RATE.test(body.rate.trim()) || Number(body.rate) > 100) {
        throw new Error('A rate is a percent, 0.00 to 100.00, with up to two decimals');
      }
      // `by` is the signed-in user the change is recorded against.
      return putJson<Rate>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`, { ...body, from: body.from.trim(), by: user ?? '' });
    },
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ratesKey(sheetId) });
      setPct('');
      setFrom('');
    },
  });

  const submit = useSubmitOnce(save);
  return (
    <section data-testid="rates-panel">
      <h2>Rates</h2>
      <form
        data-testid="rate-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit({ grade, rate: pct, from });
        }}
      >
        <label>
          Grade{' '}
          <select
            data-testid="rate-form-grade"
            value={grade}
            onChange={(e) => {
              setGrade(e.target.value);
              save.reset();
            }}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          Rate %{' '}
          <input
            data-testid="rate-form-pct"
            inputMode="decimal"
            placeholder="0.00"
            value={pct}
            onChange={(e) => {
              setPct(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <label>
          From{' '}
          <input
            type="date"
            data-testid="rate-form-from"
            value={from}
            onChange={(e) => {
              setFrom(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
          Set rate
        </button>
        {save.isError && (
          <p data-testid="rate-form-error" role="alert">
            {save.error.message}
          </p>
        )}
      </form>
      {rates.isError && (
        <p data-testid="rates-error" role="alert">
          {rates.error.message}
        </p>
      )}
      <table data-testid="rate-current-list">
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate % today</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const r = today === undefined ? undefined : rateOn(rates.data ?? [], g, today);
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`rate-current-${g}`}>{r ? showHundredths(toHundredths(r.rate)) : NA}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table data-testid="rate-list">
        <thead>
          <tr>
            <th>Grade</th>
            <th>From</th>
            <th>Rate %</th>
          </tr>
        </thead>
        <tbody>
          {(rates.data ?? []).map((r) => (
            <tr key={`${r.grade}-${r.from ?? 'start'}`} data-testid={`rate-row-${r.grade}-${r.from ?? 'start'}`}>
              <td>{r.grade}</td>
              <td data-testid="rate-from">{r.from ?? ''}</td>
              <td data-testid="rate-pct">{showHundredths(toHundredths(r.rate))}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

function DueHead() {
  return <th>Due total</th>;
}

// A person's due-total: their counted claims' due figures added up; n/a when the grade has no rate today and
// no settled or stated claim keeps a figure.
function DueTotalCell({ sheetId, personId }: { sheetId: string; user: string; personId: number }) {
  const total = useDueTotals(sheetId).get(personId);
  return <td data-testid="person-due-total">{total == null ? NA : showHundredths(total)}</td>;
}

// A claim's due: fixed when it was settled; the bound figure while a statement binds it; otherwise its amount times its person's grade's rate in
// force on the claim's date, n/a when no rate of the grade applies then.
function ClaimDue({ sheetId, personId, claim }: { sheetId: string; user: string; personId: number;
  claim: { amount: string; date: string; settledDue: string | null; stated: boolean; statedDue: string | null } }) {
  const people = usePeople(sheetId);
  const rates = useRates(sheetId);
  const grade = people.data?.find((p) => p.id === personId)?.grade;
  const due = claimDueCents(rates.data ?? [], grade, claim);
  return <span data-testid="claim-due">{due == null ? NA : showHundredths(due)}</span>;
}

// The sheet's due-total: everyone's due-total added up, skipping those that are n/a.
function DueTotal({ sheetId }: { sheetId: string; user: string }) {
  const totals = useDueTotals(sheetId);
  let sum = 0n;
  for (const t of totals.values()) if (t != null) sum += t;
  return (
    <section data-testid="due-rollup">
      <p>
        Due total: <strong data-testid="rollup-due-total">{showHundredths(sum)}</strong>
      </p>
    </section>
  );
}

export const contributions = [
  SheetBody.fill({ order: 5, Component: RatesPanel }),
  PersonHeads.fill({ order: 20, Component: DueHead }),
  PersonCells.fill({ order: 20, Component: DueTotalCell }),
  ClaimCells.fill({ order: 10, Component: ClaimDue }),
  SheetBody.fill({ order: 25, Component: DueTotal }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A grade's rate, in force from its from-date (yyyy-mm-dd); null applies from the beginning of time. */
export type Rate = { grade: string; rate: string; from: string | null };

/** The key every feature reads the sheet's rates under. */
export const ratesKey = (sheetId: string) => ['sheet', sheetId, 'rates'] as const;

/** The sheet's rates: each grade may have several, with different from-dates. */
export function useRates(sheetId: string) {
  return useQuery({
    queryKey: ratesKey(sheetId),
    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`),
  });
}

/**
 * The grade's rate in force on a date (yyyy-mm-dd): the one whose from-date is the latest on or
 * before it, a rate without a from-date counting as the earliest. Undefined when none applies.
 */
export function rateOn(rates: readonly Rate[], grade: string, date: string): Rate | undefined {
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    // ISO dates compare as text; no from-date ('') sorts before every date.
    if (found === undefined || (r.from ?? '') > (found.from ?? '')) found = r;
  }
  return found;
}

/** A two-decimal number as a whole count of hundredths ("10.25" -> 1025n), exactly. */
export function toHundredths(text: string): bigint {
  const [whole, frac = ''] = text.trim().split('.');
  return BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
}

/** Hundredths shown with two decimals. */
export function showHundredths(n: bigint): string {
  const sign = n < 0n ? '-' : '';
  const abs = n < 0n ? -n : n;
  return `${sign}${abs / 100n}.${(abs % 100n).toString().padStart(2, '0')}`;
}

/**
 * Due, in cents, on an amount (in cents) at a rate (a percent, in hundredths): amount times rate
 * divided by 100, rounded half to even to two decimals (1.025 -> 1.02, 1.035 -> 1.04). Amounts and
 * rates are never negative.
 */
export function dueCents(amountCents: bigint, rateHundredths: bigint): bigint {
  // cents * (rate/100 %) / 100 = cents * rateHundredths / 10000
  const exact = amountCents * rateHundredths;
  const whole = exact / 10000n;
  const rest = exact % 10000n;
  if (rest > 5000n || (rest === 5000n && whole % 2n === 1n)) return whole + 1n;
  return whole;
}

/** A claim's due figure in cents: fixed when it was settled; while a statement binds it, the figure it was bound to;
 *  otherwise its amount times its person's grade's rate
 *  in force on the claim's date, rounded half to even. Null when there is no figure (no rate of the grade then). */
export function claimDueCents(rates: readonly Rate[], grade: string | undefined,
  claim: { amount: string; date: string; settledDue: string | null; stated: boolean; statedDue: string | null }): bigint | null {
  if (claim.settledDue != null) return toHundredths(claim.settledDue);
  if (claim.stated) return claim.statedDue == null ? null : toHundredths(claim.statedDue);
  const found = grade === undefined ? undefined : rateOn(rates, grade, claim.date);
  return found === undefined ? null : dueCents(toHundredths(claim.amount), toHundredths(found.rate));
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { defineSlot } from '../Slot';

/**
 * The body of the screen once a user is signed in and a sheet is loaded. Every per-sheet feature
 * fills it; its context is the active sheet id and the signed-in user.
 */
export const SheetBody = defineSlot<{ sheetId: string; user: string }>('sheet.body');
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A refused request: the reason, and the HTTP status (409: someone else saved the record first). */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    // A refusal carries {"error": "<why>"}; show that, else the status line.
    const body = (await res.json().catch(() => null)) as { error?: string } | null;
    throw new HttpError(body?.error ?? `${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body?: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
}
import { useRef } from 'react';
import type { UseMutationResult } from '@tanstack/react-query';

/**
 * Runs a form's mutation, ignoring a second submit while the first has not answered (a double
 * click), so one submit stores one record. The guard is a ref, set synchronously, because a
 * second click can land before `isPending` has re-rendered the button disabled.
 */
export function useSubmitOnce<V>(mutation: UseMutationResult<unknown, Error, V, unknown>) {
  const inFlight = useRef(false);
  return (vars: V) => {
    if (inFlight.current) return;
    inFlight.current = true;
    mutation
      .mutateAsync(vars)
      .catch(() => {
        // the refusal is shown from the mutation's own error state
      })
      .finally(() => {
        inFlight.current = false;
      });
  };
}
