      }
      return putJson<Setting>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`, { key: body.key, value, by: user ?? '' });
    },
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: settingsKey(sheetId) });
    },
  });
  const submit = useSubmitOnce(save);
  return (
